import json
from dataclasses import dataclass

@dataclass
class User:
    name: str
    age: int
    email: str | None = None

def validate_model(data_str: str, model_class):
    """
    Parse and validate a JSON request body into a typed model.

    Args:
        data_str (str): JSON string representing the request body.
        model_class: A dataclass model to validate against.

    Returns:
        model_class: An instance of the model if validation succeeds.

    Raises:
        ValueError: If any required field is missing or has the wrong type.
    """
    try:
        data = json.loads(data_str)
    except json.JSONDecodeError as e:
        raise ValueError("Invalid JSON format") from e

    for field_name, field_type in model_class.__annotations__.items():
        if field_name not in data:
            raise ValueError(f"Missing required field: {field_name}")
        if not isinstance(data[field_name], field_type):
            raise ValueError(
                f"Field '{field_name}' has incorrect type: "
                f"expected '{field_type}', got '{type(data[field_name])}'"
            )

    return model_class(**data)

