import click
import os

@click.command(name='get_env')
@click.argument('key')
@click.option('--default', default=None, help='Default value if key is not found')
def get_env_command(key, default):
    """
    Get a value from the .env file or use a default if the key is not found.
    """
    env_vars = {}
    env_path = os.path.join(os.getcwd(), '.env')

    if os.path.exists(env_path):
        with open(env_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    key_part, value_part = line.split('=', 1)
                    env_vars[key_part.strip()] = value_part.strip()

    value = env_vars.get(key, default)
    click.echo(value)

