import time
from functools import wraps

def cache_with_ttl(ttl_seconds):
    cache = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Generate a unique key based on the function's arguments
            key = (args, frozenset(kwargs.items()))
            current_time = time.time()

            if key in cache:
                stored_time, result = cache[key]
                if current_time - stored_time < ttl_seconds:
                    return result

            # Compute the result and store it in the cache
            result = func(*args, **kwargs)
            cache[key] = (current_time, result)
            return result

        return wrapper

    return decorator

