import os

def get_env_value(key: str, default: str = None) -> str:
    """
    Retrieve the value of a key from the .env file, or return a default if the key is not found.

    Args:
        key (str): The key to look up in the .env file.
        default (str, optional): The default value to return if the key is not found.

    Returns:
        str: The value from the .env file or the default if the key is not found.
    """
    env_path = '.env'

    if not os.path.exists(env_path):
        return default

    try:
        with open(env_path, 'r') as env_file:
            for line in env_file:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    k, v = line.split('=', 1)
                    if k.strip() == key:
                        return v.strip()
    except Exception as e:
        # Optionally log or handle exceptions if needed
        pass

    return default
